        for (double a = -15.0; a <= 15.0; a += 0.1) {
            for (double b = -15.0; b <= 15.0; b += 0.2) {
                final double c = Angle.Rad.normalizer(b).applyAsDouble(a);
                Assertions.assertTrue(b <= c);
    }
    }
    }

